tool_calls.arguments:
{"command": "kubectl -n default patch deploy app --type=strategic -p '{
  "spec": {
    "template": {
      "spec": {
        "initContainers": [
          {
            "name": "prepare-data-perms",
            "image": "busybox:1.37.0",
            "imagePullPolicy": "IfNotPresent",
            "command": ["sh", "-ec", "mkdir -p /data && chown 1000:1000 /data && chmod 0775 /data && ls -ldn /data"],
            "securityContext": {"runAsUser": 0},
            "volumeMounts": [{"name": "data", "mountPath": "/data"}]
          }
        ]
      }
    }
  }
}' 2>&1
sleep 12; kubectl -n default get deploy app 2>&1; kubectl -n default get pods -l app=app -o wide 2>&1"}

